Constraint extractor: extract structured math constraints from LLM reasoning traces.
Input: reasoning trace string
Output: list of constraint dicts with type, expression, z3_formula, source_step
Dependencies: json, re
"""
from __future__ import annotations

import json
import logging
import re
from abc import ABC, abstractmethod
from dataclasses import dataclass, field

logger = logging.getLogger(__name__)

FEW_SHOT_EXAMPLES = """
Example 1:
Trace: "Step 1: Let x be the number of apples. Step 2: We know x + 5 = 12. Step 3: So x = 7."
Output:
{"constraints": [
  {"type": "equation", "expression": "x + 5 - 12", "z3_formula": "x + 5 == 12", "source_step": 2},
  {"type": "equation", "expression": "x - 7", "z3_formula": "x == 7", "source_step": 3}
]}

Example 2:
Trace: "Step 1: The area must be positive, so a*b > 0. Step 2: Given a + b = 10 and a*b = 21."
Output:
{"constraints": [
  {"type": "inequality", "expression": "a*b", "z3_formula": "a * b > 0", "source_step": 1},
  {"type": "equation", "expression": "a + b - 10", "z3_formula": "a + b == 10", "source_step": 2},
  {"type": "equation", "expression": "a*b - 21", "z3_formula": "a * b == 21", "source_step": 2}
]}
""".strip()

EXTRACTION_PROMPT = """You are a math constraint extractor. Given a step-by-step reasoning trace, extract all mathematical constraints (equations, inequalities, predicates) used in the reasoning.

Output a JSON object with this exact format:
{{"constraints": [
  {{"type": "equation|inequality|predicate", "expression": "sympy expression string", "z3_formula": "z3 Python expression string (e.g. x + 1 == 5)", "source_step": <step_number>}}
]}}

Rules:
- "type" must be one of: equation, inequality, predicate
- "expression" is a sympy-compatible expression (for equations, rearranged so that expr = 0)
- "z3_formula" is a z3-compatible Python expression using ==, !=, <, >, <=, >=
- "source_step" is the step number where the constraint appears
- Extract ALL constraints, including implicit ones
- Variable names should be short and consistent

{few_shot}

Now extract constraints from this trace:
{trace}

Output ONLY the JSON object, nothing else."""


class LLMBackend(ABC):
    @abstractmethod
    def call(self, prompt: str) -> str:
        ...


class MockLLM(LLMBackend):
    """Returns pre-set responses for testing."""

    def __init__(self, responses: list[str] | None = None):
        self._responses = responses or []
        self._idx = 0

    def call(self, prompt: str) -> str:
        if self._responses:
            resp = self._responses[self._idx % len(self._responses)]
            self._idx += 1
            return resp
        return json.dumps({"constraints": [
            {"type": "equation", "expression": "x - 7", "z3_formula": "x == 7", "source_step": 1},
            {"type": "equation", "expression": "x + 5 - 12", "z3_formula": "x + 5 == 12", "source_step": 2},
        ]})


@dataclass
class ExtractionStats:
    success: int = 0
    fail_json_parse: int = 0
    fail_empty: int = 0
    fail_invalid_expr: int = 0

    @property
    def total_fail(self) -> int:
        return self.fail_json_parse + self.fail_empty + self.fail_invalid_expr


class ConstraintExtractor:
    def __init__(self, llm: LLMBackend | None = None):
        self.llm = llm or MockLLM()
        self.stats = ExtractionStats()

    def _build_prompt(self, trace: str) -> str:
        return EXTRACTION_PROMPT.format(few_shot=FEW_SHOT_EXAMPLES, trace=trace)

    def extract(self, trace: str) -> list[dict]:
        """Extract structured constraints from a reasoning trace."""
        prompt = self._build_prompt(trace)
        raw = self.llm.call(prompt)

        # Parse JSON from response (handle markdown code blocks)
        json_str = raw.strip()
        m = re.search(r'```(?:json)?\s*(.*?)```', json_str, re.DOTALL)
        if m:
            json_str = m.group(1).strip()

        try:
            data = json.loads(json_str)
        except json.JSONDecodeError:
            logger.warning("JSON parse failed for trace: %s...", trace[:80])
            self.stats.fail_json_parse += 1
            return []

        constraints = data.get("constraints", [])
        if not constraints:
            self.stats.fail_empty += 1
            return []

        valid = []
        for c in constraints:
            if not all(k in c for k in ("type", "expression", "z3_formula", "source_step")):
                continue
            if c["type"] not in ("equation", "inequality", "predicate"):
                continue
            valid.append(c)

        if not valid:
            self.stats.fail_invalid_expr += 1
            return []

        self.stats.success += 1
        return valid
